head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.vScrenID = 'ULDSTF70032.xml'; // 상장원부 검토승인 


scwin.clickBzProcsNo; // 업무처리번호
scwin.clickIsuCd; // 종목코드
scwin.clickIsuNm; // 종목명
scwin.clickProcsStatCd; // 상태코드값
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/********************************************** 
 * 함수명 : fn_GetParIsur(), fn_SetParIsur()
 * 설명    : 상장신청인 호출관련
 ***********************************************/
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
    }
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    edt_SDate.setValue('19000101');
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_list_sync = function() {
    var srchIsuCd = $c.stf.getObjectValue(txb_ISU_CD);
    var url = "/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listDigitalChangeLog";
    //url += "&LD_MKT_TP=" + fr_MktId; 
    url += "&ISU_CD=" + srchIsuCd;
    url += "&STRT_DD=" + $c.stf.getObjectValue(edt_SDate);
    url += "&END_DD=" + $c.stf.getObjectValue(edt_EDate);
    url += "&LIST_PROCS_STAT=" + $c.stf.getObjectValue(cmb_PROCS_STAT_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    scwin.clickBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    scwin.clickIsuCd = dts_List.getCellData(row, "ISU_CD");
    scwin.clickIsuNm = dts_List.getCellData(row, "ISU_KOR_NM");
    scwin.clickProcsStatCd = dts_List.getCellData(row, "PROCS_STAT_CD");
    await $c.frame.CreateDialogFrame("ULDSTF70032P.gfm", "/digital/ULDSTF70032P.gfm", "상장원부(수정요청)", 20, 00, 800, 800, "window");
};
scwin.btn_Search_onclick = function() {
    // 조회 
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_List, " 상장원부 검토승인 목록", "", "2");
};
scwin.gform_onload = function() {
    // 가우스헤더 셋팅
    //dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
    //dts_StudyCond.reset();	
    scwin.fn_SetCode();
};
scwin.img_SearchIsu_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lcd.fn_PopFindDigitalIsuAll();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.txb_ISU_CD_onchange = function() {
    $c.stf.setObjectValue(txb_ISU_NM, "");
};
